-- The user's gender, which matching filters on, and the words a user who picks "other" describes it with. Existing
-- profiles have none and become incomplete until the user picks one. Stored plainly, like the other per-event answers:
-- the pool is filtered on it (data model §4).
CREATE TYPE "gender" AS ENUM ('female', 'male', 'other');

ALTER TABLE "profiles" ADD COLUMN "gender" "gender",
ADD COLUMN "gender_description" TEXT;

ALTER TABLE "profiles" ADD CONSTRAINT "profiles_gender_description_check"
    CHECK (("gender" IS NOT DISTINCT FROM 'other') = ("gender_description" IS NOT NULL));

-- Whom the user wants to go with: a gender, or anyone, and an age range; no upper bound when age_max is null. Existing
-- applications get the defaults, which filter nobody out.
CREATE TYPE "gender_preference" AS ENUM ('any', 'female', 'male');

ALTER TABLE "applications" ADD COLUMN "preferred_gender" "gender_preference" NOT NULL DEFAULT 'any',
ADD COLUMN "age_min" INTEGER NOT NULL DEFAULT 18,
ADD COLUMN "age_max" INTEGER;

ALTER TABLE "applications" ADD CONSTRAINT "applications_age_range_check"
    CHECK ("age_min" >= 18 AND ("age_max" IS NULL OR "age_max" >= "age_min"));
